// Simple endless runner based on IDEA.md
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 200;

// Game settings
let speed = 2; // base scroll speed (pixels/frame)
const speedIncrement = 0.001; // accelerate over time
const gravity = 0.6;
const jumpStrength = -12;

// Player block
const player = {
  x: 50,
  y: canvas.height - 40,
  width: 30,
  height: 30,
  vy: 0,
  onGround: true,
  draw() {
    ctx.fillStyle = '#4A90E2';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  },
  update() {
    this.vy += gravity;
    this.y += this.vy;
    if (this.y + this.height >= canvas.height) {
      this.y = canvas.height - this.height;
      this.vy = 0;
      this.onGround = true;
    } else {
      this.onGround = false;
    }
  },
  jump() {
    if (this.onGround) {
      this.vy = jumpStrength;
      this.onGround = false;
    }
  }
};

// Spikes
const spikes = [];
const spikeWidth = 20;
const spikeHeight = 30;
let spikeTimer = 0;
const spikeInterval = 90; // frames between spikes (adjusted by speed)

function addSpike() {
  spikes.push({
    x: canvas.width,
    y: canvas.height - spikeHeight,
    width: spikeWidth,
    height: spikeHeight
  });
}

function updateSpikes() {
  for (let i = spikes.length - 1; i >= 0; i--) {
    const s = spikes[i];
    s.x -= speed;
    if (s.x + s.width < 0) spikes.splice(i, 1);
  }
}

function drawSpikes() {
  ctx.fillStyle = '#D0021B';
  spikes.forEach(s => ctx.fillRect(s.x, s.y, s.width, s.height));
}

function checkCollision() {
  for (const s of spikes) {
    if (
      player.x < s.x + s.width &&
      player.x + player.width > s.x &&
      player.y < s.y + s.height &&
      player.y + player.height > s.y
    ) {
      return true;
    }
  }
  return false;
}

let gameOver = false;
function gameLoop() {
  if (gameOver) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Update speed gradually
  speed += speedIncrement;

  // Player update
  player.update();
  player.draw();

  // Spike handling
  spikeTimer++;
  if (spikeTimer > spikeInterval / speed) { // faster spikes as speed rises
    addSpike();
    spikeTimer = 0;
  }
  updateSpikes();
  drawSpikes();

  // Collision detection
  if (checkCollision()) {
    gameOver = true;
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#FFF';
    ctx.font = '30px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    return;
  }

  requestAnimationFrame(gameLoop);
}

// Input handling
window.addEventListener('keydown', e => {
  if (e.code === 'Space') {
    e.preventDefault();
    player.jump();
  }
});

// Start
requestAnimationFrame(gameLoop);
